command:
$ErrorActionPreference="Stop"
$base="70e93203ac628744a4f85c4b8bc6466f308bbcb2"
$candidate="7cd134456d0ed020d1008858a579ba41900d2902"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$worktree=Join-Path $env:RUNNER_TEMP "fly-indexed-size-7cd13445"
Set-Location -LiteralPath $repo
if(Test-Path -LiteralPath $worktree){throw "Owned worktree path already exists"}
& git fetch origin main feat/search-v3-indexed-size --no-tags
if($LASTEXITCODE -ne 0){throw "Git fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($observed -ne $base){throw "Current main moved"}
$candidateRef=(& git rev-parse refs/remotes/origin/feat/search-v3-indexed-size).Trim()
if($candidateRef -ne $candidate){throw "Candidate ref moved"}
try {
  & git worktree add --detach $worktree $candidate
  if($LASTEXITCODE -ne 0){throw "Worktree creation failed"}
  Set-Location -LiteralPath $worktree
  & python -X utf8 -m py_compile tests/winui/test_indexed_search_contract.py tests/winui/test_indexed_search_native.py tests/winui/test_indexed_search_gui.py tests/winui/m19/test_native.py
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_PY_COMPILE_FAIL"}
  & python -X utf8 -m unittest tests/winui/test_indexed_search_contract.py
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_SOURCE_FAIL"}
  Write-Host "INDEXED_SIZE_SOURCE=PASS"
  & cmd.exe /c tests\winui\m19\build.cmd Release
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_NATIVE_BUILD_FAIL"}
  $env:FLY_M19_CONFIG="Release"
  & python -X utf8 tests/winui/m19/test_native.py
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_M19_NATIVE_FAIL"}
  Write-Host "INDEXED_SIZE_M19_NATIVE=PASS"
  & cmd.exe /c build.bat Release
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_RELEASE_BUILD_FAIL"}
  Write-Host "INDEXED_SIZE_RELEASE_BUILD=PASS"
  & python -X utf8 tests/winui/test_indexed_search_native.py --configuration Release
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_SYSTEMINDEX_FAIL"}
  Write-Host "INDEXED_SIZE_SYSTEMINDEX=PASS"
  & python -X utf8 tests/winui/test_indexed_search_gui.py --configuration Release --capture after
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_GUI_FAIL"}
  Write-Host "INDEXED_SIZE_GUI=PASS"
  & git diff --check
  if($LASTEXITCODE -ne 0){throw "INDEXED_SIZE_DIFF_FAIL"}
  Write-Host "INDEXED_SIZE_FOCUSED_ACCEPTANCE=PASS"
} finally {
  Remove-Item Env:FLY_M19_CONFIG -ErrorAction SilentlyContinue
  Set-Location -LiteralPath $repo
  if(Test-Path -LiteralPath $worktree){& git worktree remove --force $worktree}
  & git worktree prune
}
